function reactive(obj, onChange) {
  return new Proxy(obj, {
    get(t, k, r) {
      const v = Reflect.get(t, k, r);
      return v && typeof v === 'object' ? reactive(v, onChange) : v;
    },
    set(t, k, v, r) {
      const ok = Reflect.set(t, k, v, r);
      if (ok) onChange(k);
      return ok;
    },
    deleteProperty(t, k) { const ok = Reflect.deleteProperty(t, k); if (ok) onChange(k); return ok; }
  });
}
// Limite : chaque get recrée un Proxy → mets un WeakMap en cache.
