Pourquoi ça rame sur 500 éléments, et comment corriger ?

solution:
```js
async function retry(fn, { tries = 4, baseDelay = 300, signal } = {}) {
  for (let n = 0; ; n++) {
    try { return await fn({ signal }); }
    catch (e) {
      if (e.status >= 400 && e.status < 500) throw e; // inutile de réessayer
      if (n >= tries - 1 || signal?.aborted) throw e;
      const wait = baseDelay * 2 ** n * (0.5 + Math.random()); // jitter
      await new Promise((res, rej) => {
        const t = setTimeout(res, wait);
        signal?.addEventListener('abort', () => { clearTimeout(t); rej(signal.reason); }, { once: true });
      });
    }
  }
}
```

```js
class LRU {
  #map = new Map();
  constructor(capacity) { this.capacity = capacity; }
  get(k) {
    if (!this.#map.has(k)) return undefined;
    const v = this.#map.get(k);
    this.#map.delete(k); this.#map.set(k, v); // repousse en fin
    return v;
  }
  set(k, v) {
    this.#map.delete(k);
    this.#map.set(k, v);
    if (this.#map.size > this.capacity) this.#map.delete(this.#map.keys().next().value);
  }
}
// Map garde l'ordre d'insertion → pas besoin de liste chaînée.
```

