class Emitter {
  #m = new Map();
  on(e, fn) { (this.#m.get(e) ?? this.#m.set(e, new Set()).get(e)).add(fn); return () => this.off(e, fn); }
  once(e, fn) {
    const wrap = (...a) => { this.off(e, wrap); fn(...a); };
    wrap.orig = fn; // clé du problème
    return this.on(e, wrap);
  }
  off(e, fn) {
    const set = this.#m.get(e);
    if (!set) return;
    for (const h of set) if (h === fn || h.orig === fn) set.delete(h);
  }
  emit(e, ...a) { for (const h of [...(this.#m.get(e) ?? [])]) h(...a); }
}
// emit itère une COPIE : un handler qui se désabonne ne casse pas la boucle.
```

