const unflat = (o) => {
  const root = {};
  for (const [path, v] of Object.entries(o)) {
    const keys = path.split('.');
    keys.reduce((acc, k, i) =>
      i === keys.length - 1 ? (acc[k] = v)
      : acc[k] ??= (/^\d+$/.test(keys[i + 1]) ? [] : {}), root);
  }
  return root;
};
